Given a very large number N in the form of a string and a number K, the task is to print all the K-digit repeating numbers whose frequency is greater than 1. Examples:Input: str = "123412345123456", K = 4 Output: 1234 - 3 2345 - 2 Explanation: The 4-digit numbers having frequency greater than 1 are 1234 and 2345.Input: N = 1432543214325432, K = 5 Output: 14325 - 2 32543 - 2 43254 - 2 Explanation: The 5-digit numbers having frequency greater than 1 are 14325, 32543, and 43254.Approach: Since the number is given in the form of a string, the idea is to store all the substring of size K in a map with their frequency. Now, while iterating the Map, it prints only those substrings which have a frequency greater than one along with the number of times they appear.Below is the implementation of the above approach:
            C++

    // C++ program for the above approach 
#include <bits/stdc++.h> 
using namespace std; 

// Function to print all K digit 
// repeating numbers 
void print_Kdigit(string S, int K) 
{ 
    // Map to store the substrings 
    // with their frequencies 
    map<string, int> m; 

    // Iterate over every substring 
    // and store their frequencies 
    // in the map 
    for (int i = 0; i <= S.length() - K; i++) { 
        string a = S.substr(i, K); 

        // Increment the count of 
        // substrings in map 
        m[a]++; 
    } 

    // Iterate over all the substrings 
    // present in the map 
    for (auto x : m) { 
        // Condition to check if the 
        // frequency of the substring 
        // present in the map 
        // is greater than 1 
        if (x.second > 1) { 
            cout << x.first << " - "
                << x.second << "\n"; 
        } 
    } 
} 

// Driver Code 
int main() 
{ 
    // Given Number in form of string 
    string str = "123412345123456"; 

    // Given K 
    int K = 4; 

    // Function Call 
    print_Kdigit(str, K); 

    return 0;
} 
